shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --accent: #b85d19;
    --navy-bg: #0f1d2b;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    font-family: 'Noto Serif SC', 'Lora', Georgia, serif;
    background-color: var(--paper);
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: 'Lora', Georgia, serif;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: rgba(250, 248, 244, 0.96);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--ink);
    box-shadow: 0 1px 0 var(--line);
  }

  .masthead-inner {
    max-width: 960px;
    margin: 0 auto;
    padding: 0.75rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-cluster {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  .wsj-logo {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .section-badge {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    border-left: 1px solid var(--line);
    padding-left: 0.75rem;
  }

  .lang-switch {
    display: inline-flex;
    align-items: center;
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-radius: 3px;
    padding: 2px;
  }

  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.3rem 0.65rem;
    color: var(--muted);
    cursor: pointer;
    border-radius: 2px;
    transition: all 0.15s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Editorial Container */
  .dispatch-wrapper {
    flex: 1;
    width: 100%;
    max-width: 780px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 4.5rem;
  }

  /* Print-inspired Newspaper Brief Frame */
  .brief-card {
    background: var(--paper);
    border-top: 3px double var(--ink);
    border-bottom: 1px solid var(--ink);
    padding: 2.25rem 0 2.5rem;
  }

  /* Meta Dateline Bar */
  .meta-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-bottom: 1.25rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--line);
  }

  .dateline-loc {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .dateline-loc::before {
    content: "";
    display: inline-block;
    width: 7px;
    height: 7px;
    background-color: var(--accent);
    border-radius: 50%;
  }

  .edition-code {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    color: var(--muted);
    letter-spacing: 0.04em;
  }

  /* Headline */
  .headline {
    font-family: 'Noto Serif SC', 'Playfair Display', Georgia, serif;
    font-weight: 700;
    font-size: clamp(1.85rem, 4vw, 2.55rem);
    line-height: 1.25;
    color: var(--ink);
    margin-bottom: 1rem;
    letter-spacing: -0.01em;
  }

  :host([lang="en"]) .headline {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 800;
    line-height: 1.15;
  }

  /* Byline & Timestamp */
  .byline-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    color: var(--muted);
    margin-bottom: 2rem;
    padding-bottom: 1.25rem;
    border-bottom: 1px solid var(--line);
  }

  .byline-source {
    font-weight: 600;
    color: var(--ink);
  }

  .byline-date {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.76rem;
    color: var(--muted);
  }

  /* Two-Column Asymmetric Dispatch Grid */
  .dispatch-grid {
    display: grid;
    grid-template-columns: 1fr 220px;
    gap: 2.5rem;
    align-items: start;
  }

  .prose-column {
    min-width: 0;
  }

  .prose-p {
    font-size: 1.125rem;
    line-height: 1.9;
    color: var(--body);
    margin-bottom: 1.5rem;
    text-align: left;
  }

  .prose-p:last-child {
    margin-bottom: 0;
  }

  /* Lead paragraph treatment (no ::first-letter on Chinese text) */
  .prose-p.lead-p {
    font-size: 1.2rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.1rem;
    margin-bottom: 1.65rem;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.12rem;
    line-height: 1.8;
  }

  :host([lang="en"]) .prose-p.lead-p {
    font-size: 1.22rem;
    font-weight: 400;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 62%, rgba(184, 93, 25, 0.18) 62%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
  }

  /* Compact Dossier Rail */
  .dossier-rail {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-top: 2px solid var(--ink);
    padding: 1.15rem 1.1rem;
  }

  .dossier-title {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    padding-bottom: 0.6rem;
    margin-bottom: 0.85rem;
    border-bottom: 1px solid var(--line);
  }

  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }

  .dossier-item {
    display: flex;
    flex-direction: column;
    gap: 0.18rem;
  }

  .dossier-key {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--muted);
  }

  .dossier-val {
    font-family: 'Noto Serif SC', 'Lora', serif;
    font-size: 0.88rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.4;
  }

  .dossier-val.mono {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.82rem;
    color: var(--accent);
  }

  /* Footer Colophon */
  .colophon {
    max-width: 780px;
    width: 100%;
    margin: 0 auto;
    padding: 0 1.5rem 3rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.75rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 680px) {
    .dispatch-wrapper {
      padding: 2rem 1.15rem 3rem;
    }

    .dispatch-grid {
      grid-template-columns: 1fr;
      gap: 1.75rem;
    }

    .masthead-inner {
      padding: 0.65rem 1.15rem;
    }

    .section-badge {
      display: none;
    }

    .prose-p.lead-p {
      font-size: 1.12rem;
      padding-left: 0.85rem;
    }

    .prose-p {
      font-size: 1.05rem;
    }
  }
